/**
 * Design-exploration data (round 0): real MNI152NLin2009cAsym 1 mm slices
 * rendered to PNG and MOCK hippocampal subfield labels, generated by
 * `tools/design/segmentation_assets.py`. Used only by the direction mocks and
 * the dev harness; the shipping workspace never imports this file.
 */

import slices from '@/modules/segmentation/__design__/assets/slices.json';
import type { LabelVoxel, Plane, SliceImage } from '@/modules/segmentation/components/shared/types';

const PNG_URLS = import.meta.glob('./assets/*.png', {
  eager: true,
  import: 'default',
  query: '?url',
}) as Record<string, string>;

interface RawImage {
  file: string;
  plane: string;
  index: number;
  contrast: string;
  cols: number;
  rows: number;
}

interface RawLabels {
  plane: string;
  index: number;
  voxels: number[][];
}

const CONTRAST_NAME: Record<string, string> = {
  t2: 'T2w',
  t1: 'T1w',
  't2-unsharp': 'T2w · unsharp',
};

function image(name: string): SliceImage {
  const raw = (slices.images as Record<string, RawImage>)[name];
  if (!raw) throw new Error(`segmentation design: no image "${name}"`);
  const url = PNG_URLS[`./assets/${raw.file}`] ?? raw.file;
  return {
    key: name,
    url,
    plane: raw.plane as Plane,
    index: raw.index,
    contrast: CONTRAST_NAME[raw.contrast] ?? raw.contrast,
    viewOnly: raw.contrast === 't2-unsharp',
    cols: raw.cols,
    rows: raw.rows,
  };
}

function labels(name: string): LabelVoxel[] {
  const raw = (slices.labels as Record<string, RawLabels>)[name];
  if (!raw) throw new Error(`segmentation design: no label slice "${name}"`);
  return raw.voxels.map(([c, r, l]) => [c, r, l] as LabelVoxel);
}

const P = slices.primary;
const AX = String(P.axialK).padStart(3, '0');
const SAG = String(P.sagittalI).padStart(3, '0');

interface RawReviewLabel {
  volA: number;
  volB: number;
  dice: number | null;
  hd95: number | null;
  disagreeBySlice: number[];
}

const AREA = slices.areaBySlice as unknown as { j: [number, number]; traced: Record<string, number[]>; all: Record<string, number[]> };
const REVIEW_RAW = slices.review as unknown as {
  j: [number, number];
  regions: number;
  regionsBySlice: Record<string, number>;
  labels: Record<string, RawReviewLabel>;
};

export const DESIGN = {
  source: slices.source,
  grid: slices.grid,
  counts: slices.counts as Record<string, number>,
  tracedJ: slices.tracedJ as [number, number],
  hippocampusRangeJ: slices.hippocampusRangeJ as [number, number],
  /** Hippocampus centre on the primary coronal slice (display px). */
  hippoCentre: slices.hippocampusCentre as [number, number],
  strokeCa1: slices.strokeCa1 as Array<[number, number]>,
  strokeDg: slices.strokeDg as Array<[number, number]>,
  /** Label area (voxels) on every coronal slice j in `area.j` (inclusive). */
  area: AREA,
  /** Rater A (full mock labels) against rater B over the same range. */
  review: REVIEW_RAW,
  primaryJ: P.j,
  axialK: P.axialK,
  sagittalI: P.sagittalI,
  images: {
    corT2: image(`cor${P.j}_t2`),
    corT1: image(`cor${P.j}_t1`),
    corT2u: image(`cor${P.j}_t2u`),
    cor: (j: number) => image(`cor${j}_t2`),
    axT2: image(`ax${AX}_t2`),
    axT1: image(`ax${AX}_t1`),
    sagT2: image(`sag${SAG}_t2`),
    sagT1: image(`sag${SAG}_t1`),
  },
  labels: {
    /** Rater A's full mock labels on a coronal slice. */
    cor: (j: number) => labels(`cor${j}`),
    raterB: labels(`cor${P.j}_raterB`),
    axTraced: labels(`ax${AX}_traced`),
    sagTraced: labels(`sag${SAG}_traced`),
    axAll: labels(`ax${AX}_all`),
    sagAll: labels(`sag${SAG}_all`),
  },
} as const;

export type DesignData = typeof DESIGN;
